import axios from "axios";
import MaterialTable from "material-table";
import React, { Component } from "react";
import {
  MdAddCircle,
  MdCheckCircle,
  MdEdit,
  MdRemoveCircle
} from "react-icons/md";
import { connect } from "react-redux";
import { Button, Card, CardBody, CardHeader, Input, Spinner } from "reactstrap";
import { tokenConfig } from "../../actions/authActions";
import store from "../../store";

class Clients extends Component {
  state = {
    addRow: false,
    rowData: [],
    clientsLoaded: false,
    newClientName: "",
    editRowIndex: -1,
    editClientName: "",
    editClientNamePlaceholder: ""
  };

  componentDidMount() {
    this.retrieveClients();
  }

  retrieveClients = () => {
    this.setState(state => ({
      clientsLoaded: false,
      rowData: state.rowData
    }));
    axios
      .get("/api/clients")
      .then(res => {
        var rowData = res.data.map((x, index) => {
          return {
            id: x._id,
            name: x.name,
            created_by: x.createdByUserId.name
          };
        });
        this.setState(state => ({
          clientsLoaded: true,
          rowData
        }));
      })
      .catch(err => console.log(err));
  };

  editRow = index => {
    //if the incoming  Index= same as current, change the name back from the input to the editClientNamePlaceholder,set editClientNamePlaceholder="" , change editRowIndex to -1
    //if the incoming Index= different than current and current!= -1, chnage the current editRow back to the editClientNamePlaceholder, set the new editClientNamePlaceholder, change editRowIndex to the new index
    //if the current index=-1, chnage the current editRow back to the editClientNamePlaceholder, set the new editClientNamePlaceholder , change editRowIndex to the new index
    if (this.state.addRow) {
      this.addRow();
    }
    if (this.state.editRowIndex === -1) {
      //toggle on current edit row
      const rowData = this.state.rowData;
      var nameHolder = this.state.rowData[index].name;
      rowData[index] = {
        id: this.state.rowData[index].id,
        name: (
          <Input
            type="text"
            name="editClientName" //has to match the name of the variable in the state
            defaultValue={this.state.rowData[index].name}
            onChange={this.onChange}
          />
        ),
        created_by: this.state.rowData[index].created_by,
        actions: (
          <div>
            <Button
              className="float-left"
              color="dark"
              onClick={this.editClient.bind(
                this,
                index,
                this.state.rowData[index].id
              )} ////////////////
            >
              <MdCheckCircle />
            </Button>
            <Button
              className="float-left ml-1"
              color="dark"
              onClick={this.removeClient.bind(
                this,
                this.state.rowData[index].id
              )}
            >
              <MdRemoveCircle />
            </Button>
          </div>
        )
      };
      this.setState(state => ({
        editRowIndex: index,
        editClientNamePlaceholder: nameHolder,
        editClientName: nameHolder,
        rowData
      }));
    } else if (index !== this.state.editRowIndex) {
      //toggle off last editRow
      var nameHolder = this.state.rowData[index].name;
      const rowData = this.state.rowData;
      rowData[this.state.editRowIndex] = {
        id: this.state.rowData[this.state.editRowIndex].id,
        name: this.state.editClientNamePlaceholder,
        created_by: this.state.rowData[this.state.editRowIndex].created_by,
        actions: (
          <div>
            <Button
              className="float-left"
              color="dark"
              onClick={this.editRow.bind(this, this.state.editRowIndex)}
            >
              <MdEdit />
            </Button>
            <Button
              className="float-left ml-1"
              color="dark"
              onClick={this.removeClient.bind(
                this,
                this.state.rowData[index].id
              )}
            >
              <MdRemoveCircle />
            </Button>
          </div>
        )
      };
      //toggle on current edit row
      rowData[index] = {
        id: this.state.rowData[index].id,
        name: (
          <Input
            type="text"
            name="editClientName" //has to match the name of the variable in the state
            defaultValue={this.state.rowData[index].name}
            onChange={this.onChange}
          ></Input>
        ),
        created_by: this.state.rowData[index].created_by,
        actions: (
          <div>
            <Button
              className="float-left"
              color="dark"
              onClick={this.editClient.bind(
                this,
                index,
                this.state.rowData[index].id
              )}
            >
              <MdCheckCircle />
            </Button>
            <Button
              className="float-left ml-1"
              color="dark"
              onClick={this.removeClient.bind(
                this,
                this.state.rowData[index].id
              )}
            >
              <MdRemoveCircle />
            </Button>
          </div>
        )
      };
      this.setState(state => ({
        editClientNamePlaceholder: nameHolder,
        editClientName: nameHolder,
        editRowIndex: index,
        rowData
      }));
    } else if (index === this.state.editRowIndex) {
      //toggle off last editRow
      //dont toggle on current editRow(same row)

      const rowData = this.state.rowData;
      rowData[this.state.editRowIndex] = {
        id: this.state.rowData[this.state.editRowIndex].id,
        name: this.state.editClientNamePlaceholder,
        created_by: this.state.rowData[this.state.editRowIndex].created_by,
        actions: (
          <div>
            <Button
              className="float-left"
              color="dark"
              onClick={this.editRow.bind(this, this.state.editRowIndex)}
            >
              <MdEdit />
            </Button>
            <Button
              className="float-left ml-1"
              color="dark"
              onClick={this.removeClient.bind(
                this,
                this.state.rowData[index].id
              )}
            >
              <MdRemoveCircle />
            </Button>
          </div>
        )
      };

      this.setState(state => ({
        editRowIndex: -1,
        editClientNamePlaceholder: ""
      }));
    }
  };

  editClient = (index, id) => {
    if (this.state.editClientNamePlaceholder === this.state.editClientName) {
      this.editRow(index);
    } else {
      const modifiedClient = {
        name: this.state.editClientName,
        userId: this.props.auth.isAuthenticated
          ? this.props.auth.user._id
          : "Guest"
      };
      axios
        .put(`/api/clients/${id}`, modifiedClient, tokenConfig(store.getState))
        .then(res => {
          console.log(res.data);
          this.retrieveClients();
        })
        .catch(err => console.log(err.data));
    }
  };

  removeClient = id => {
    axios
      .delete(`/api/clients/${id}`, tokenConfig(store.getState))
      .then(res => {
        console.log(res.data);
        this.retrieveClients();
      })
      .catch(err => console.log(err.data));
  };

  onChange = e => {
    this.setState({ [e.target.name]: e.target.value });
  };

  render() {
    return (
      <div>
        <Button className="float-right" color="dark" onClick={this.addRow}>
          <MdAddCircle />
        </Button>
        {this.state.clientsLoaded ? (
          <MaterialTable
            columns={[
              { title: "ID", field: "id", editable: "never" },
              { title: "Name", field: "name" },
              {
                title: "Created By",
                field: "created_by",
                editable: "never",
                initialEditValue: this.props.auth.isAuthenticated
                  ? this.props.auth.user.name
                  : "Guest"
              }
            ]}
            data={this.state.rowData}
            title="Clients"
            options={{
              actionsColumnIndex: 3,
              addRowPosition: "first"
            }}
            editable={{
              onRowAdd: newData =>
                new Promise((resolve, reject) => {
                  setTimeout(() => {
                    {
                      const newClient = {
                        name: newData.name,
                        userId: this.props.auth.isAuthenticated
                          ? this.props.auth.user._id
                          : "Guest"
                      };
                      axios
                        .post(
                          "/api/clients",
                          newClient,
                          tokenConfig(store.getState)
                        )
                        .then(res => {
                          console.log(res.data);
                          this.retrieveClients();
                        })
                        .catch(err => console.log(err.data));
                    }
                    resolve();
                  }, 10);
                }),
              onRowUpdate: (newData, oldData) =>
                new Promise((resolve, reject) => {
                  setTimeout(() => {
                    {
                      console.log(newData);
                    }
                    resolve();
                  }, 1000);
                }),
              onRowDelete: oldData =>
                new Promise((resolve, reject) => {
                  setTimeout(() => {
                    {
                      console.log(oldData.id);

                      axios
                        .delete(
                          `/api/clients/${oldData.id}`,
                          tokenConfig(store.getState)
                        )
                        .then(res => {
                          console.log(res.data);
                          this.retrieveClients();
                        })
                        .catch(err => console.log(err.data));
                    }
                    resolve();
                  }, 1000);
                })
            }}
          />
        ) : (
          <div
            style={{
              display: "flex",
              justifyContent: "center"
            }}
          >
            <Spinner animation="border" />
          </div>
        )}
      </div>
    );
  }
}

const mapStateToProps = state => ({
  //posts is from the root reducer. Items is from the postReducer, which is ultimately getting the action from the postAction.  This expression then allows for use of this.props.posts
  auth: state.auth
});

//export default connect(mapStateToProps, {postClient,getClients,deleteClient})(Clients);
export default connect(mapStateToProps, null)(Clients);
